<script setup lang="ts">
import { SearchableSelect } from '#components'
const { t } = useLanguage()
const db=useSupabase(),summary=ref<any>(null),history=ref<any[]>([]),error=ref(''),success=ref(''),busy=ref(false),key=useRequestKey()
const form=reactive({owner:'',amount:0,date:todayKarachi(),note:''}),expenseForm=reactive({category:'',description:'',amount:0,date:todayKarachi()})
const bookExpenses=ref<any[]>([])
async function load(){if(!db)return;busy.value=true;error.value='';try{const q=await db.rpc('independent_book_summary');if(q.error)throw q.error;summary.value=q.data;history.value=await allRows(()=>db.from('book_owner_settlements').select('*').order('created_at',{ascending:false}).order('id'));bookExpenses.value=await allRows(()=>db.from('book_expenses').select('*').order('spent_on',{ascending:false}).order('created_at',{ascending:false}))}catch(e){error.value=errText(e)}finally{busy.value=false}}
async function pay(){if(!db||busy.value||!window.confirm(t('financialUi.bookOwners.confirmPayment')))return;busy.value=true;try{const q=await db.rpc('settle_book_owner',{p_owner:form.owner,p_amount:form.amount,p_date:form.date,p_note:form.note,p_request:key.forPayload(form)});if(q.error)throw q.error;key.reset();form.amount=0;success.value=t('financialUi.bookOwners.paymentSaved');await load()}catch(e){error.value=errText(e)}finally{busy.value=false}}
async function cancel(r:any){if(!db||busy.value)return;const reason=window.prompt(t('financialUi.bookOwners.voidPrompt'));if(!reason)return;busy.value=true;try{const q=await db.rpc('void_book_owner_settlement',{p_id:r.id,p_reason:reason});if(q.error)throw q.error;await load()}catch(e){error.value=errText(e)}finally{busy.value=false}}
async function saveBookExpense(){if(!db||busy.value)return;busy.value=true;error.value='';try{const q=await db.rpc('record_book_expense',{p_category:expenseForm.category,p_description:expenseForm.description,p_amount:expenseForm.amount,p_spent_on:expenseForm.date,p_request:crypto.randomUUID()});if(q.error)throw q.error;expenseForm.description='';expenseForm.amount=0;success.value=t('financialUi.expenses.saved');await load()}catch(e){error.value=errText(e)}finally{busy.value=false}}
async function voidBookExpense(row:any){if(!db||busy.value)return;const reason=window.prompt(t('financialUi.bookOwners.voidPrompt'));if(!reason)return;busy.value=true;try{const q=await db.rpc('void_book_expense',{p_id:row.id,p_reason:reason});if(q.error)throw q.error;await load()}catch(e){error.value=errText(e)}finally{busy.value=false}}
onMounted(load)
</script>
<template><section class="card no-print" style="margin-top:20px"><div class="card-header"><h3>{{ t('financialUi.bookOwners.title') }}</h3><button class="btn" :disabled="busy" @click="load">{{ t('financialUi.bookOwners.refresh') }}</button></div><Notice :message="error" kind="error"/><Notice :message="success" kind="success"/><template v-if="summary"><p class="hint">{{ t('financialUi.bookOwners.note') }}</p><div class="table-wrap"><table class="data-table"><thead><tr><th>{{ t('financialUi.materials.owner') }}</th><th>{{ t('financialUi.bookOwners.collectedFromStudents') }}</th><th>{{ t('financialUi.bookOwners.paidToOwner') }}</th><th>{{ t('financialUi.bookOwners.heldForOwner') }}</th></tr></thead><tbody><tr v-for="o in summary.owners" :key="o.owner_name"><td>{{o.owner_name}}</td><td>{{money(o.collected)}}</td><td>{{money(o.paid_to_owner)}}</td><td>{{money(o.held_for_owner)}}</td></tr></tbody></table></div><form @submit.prevent="pay"><div class="form-grid"><label>{{ t('financialUi.materials.owner') }}<SearchableSelect v-model="form.owner" :options="summary.owners" label-key="owner_name" value-key="owner_name" :placeholder="t('financialUi.select')" :min-chars="2" required /></label><label>{{ t('financialUi.amount') }}<input v-model.number="form.amount" type="number" min="0.01" step="0.01" required/></label><label>{{ t('financialUi.date') }}<input v-model="form.date" type="date" required/></label><label>{{ t('financialUi.description') }}<input v-model="form.note" required/></label></div><div class="form-footer"><button class="btn primary" :disabled="busy">{{ t('financialUi.bookOwners.confirmPaymentButton') }}</button></div></form><details><summary>{{ t('financialUi.bookOwners.history') }}</summary><div v-for="r in history" :key="r.id" class="quick-item"><span>{{r.owner_name}} · {{r.paid_on}} · {{money(r.amount)}} · {{r.voided_at?t('financialUi.expenses.voidedReason',{reason:r.void_reason}):r.note}}</span><button v-if="!r.voided_at" class="btn small-btn danger" :disabled="busy" @click="cancel(r)">{{ t('financialUi.void') }}</button></div></details><hr/><h3>{{ t('financialUi.materials.books') }} · {{ t('financialUi.expenses.title') }}</h3><p class="hint">{{ t('financialUi.bookOwners.note') }} · {{ t('financialUi.expenses.total') }}: {{ money(bookExpenses.filter(row => !row.voided_at).reduce((sum,row) => sum+Number(row.amount),0)) }}</p><form @submit.prevent="saveBookExpense"><div class="form-grid"><label>{{ t('financialUi.category') }}<input v-model="expenseForm.category" required/></label><label>{{ t('financialUi.description') }}<input v-model="expenseForm.description" required/></label><label>{{ t('financialUi.amount') }}<input v-model.number="expenseForm.amount" type="number" min="0.01" step="0.01" required/></label><label>{{ t('financialUi.date') }}<input v-model="expenseForm.date" type="date" required/></label></div><div class="form-footer"><button class="btn primary" :disabled="busy">{{ t('financialUi.expenses.new') }}</button></div></form><div v-for="row in bookExpenses" :key="row.id" class="quick-item"><span>{{ row.spent_on }} · {{ row.category }} · {{ row.description }} · {{ money(row.amount) }}<small v-if="row.voided_at">{{ t('financialUi.expenses.voidedReason',{reason:row.void_reason}) }}</small></span><button v-if="!row.voided_at" class="btn small-btn danger" :disabled="busy" @click="voidBookExpense(row)">{{ t('financialUi.void') }}</button></div></template></section></template>
